-- Canonical relational schema for a fresh PostgreSQL installation.
-- The application startup uses the same tables for local SQLite convenience.
CREATE TABLE IF NOT EXISTS participants (id SERIAL PRIMARY KEY, code TEXT NOT NULL UNIQUE, reset_group TEXT NOT NULL DEFAULT 'default', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS lessons (id TEXT PRIMARY KEY, title TEXT NOT NULL, summary TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, participant_id INTEGER NOT NULL REFERENCES participants(id), mode TEXT NOT NULL, lesson_id TEXT NOT NULL REFERENCES lessons(id), access_token TEXT NOT NULL DEFAULT '', study_kind TEXT NOT NULL DEFAULT 'practice', camera_consent INTEGER NOT NULL DEFAULT 0, data_origin TEXT NOT NULL DEFAULT 'observed', content_version TEXT NOT NULL DEFAULT 'v1', policy_version TEXT NOT NULL DEFAULT 'v1', reset_group TEXT NOT NULL DEFAULT 'default', progress_phase TEXT NOT NULL DEFAULT 'pre', progress_question_id TEXT, progress_question_index INTEGER NOT NULL DEFAULT 0, progress_section_id TEXT NOT NULL DEFAULT 'explain', section_visits TEXT NOT NULL DEFAULT '{}', active_time_ms INTEGER NOT NULL DEFAULT 0, elapsed_time_ms INTEGER NOT NULL DEFAULT 0, started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ended_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS events (id SERIAL PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), client_event_id TEXT NOT NULL, event_type TEXT NOT NULL, payload TEXT NOT NULL, decision_json TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id, client_event_id));
CREATE TABLE IF NOT EXISTS answers (id SERIAL PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), question_id TEXT NOT NULL, phase TEXT NOT NULL, concept TEXT NOT NULL, answer TEXT NOT NULL, correct INTEGER NOT NULL, response_time_ms INTEGER, response_started_at TEXT, submitted_at TIMESTAMP, section_id TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id, question_id, phase));
CREATE TABLE IF NOT EXISTS interventions (id SERIAL PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), concept TEXT NOT NULL, kind TEXT NOT NULL, trigger TEXT NOT NULL, reason TEXT NOT NULL, selection_reason TEXT NOT NULL DEFAULT '', follow_up_bank TEXT NOT NULL DEFAULT 'follow_up', status TEXT NOT NULL DEFAULT 'offered', accepted INTEGER, viewed_at TIMESTAMP, skipped_at TIMESTAMP, completed_at TIMESTAMP, dismissed_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS follow_ups (id SERIAL PRIMARY KEY, intervention_id INTEGER NOT NULL REFERENCES interventions(id), question_id TEXT NOT NULL, answer TEXT, correct INTEGER NOT NULL, helpfulness INTEGER, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(intervention_id, question_id));
